#!/bin/bash
# Generated by v32as. Edit the sources (or delete this line and keep a hand-written script)
# rather than this file: it is rewritten by v32as --build-scripts.
# Set V32AS, V32OPT, PACKROM, PNG2VIRCON or WAV2VIRCON to use a tool that is not in the PATH,
# and V32OPT_FLAGS (default -O3) to change how v32opt optimizes.

cd -- "$(dirname -- "${BASH_SOURCE[0]:-$0}")" || exit 1
# tell any v32as started from here not to rewrite the scripts that are running
export V32AS_BUILD_SCRIPT=1

abort_build()
{
    echo
    echo BUILD FAILED
    exit 1
}

need_tool()
{
    command -v "$1" >/dev/null 2>&1 || { echo "ERROR: $1 is needed to build, but was not found in PATH"; abort_build; }
}

V32AS="${V32AS:-v32as}"
PACKROM="${PACKROM:-packrom}"
V32OPT="${V32OPT:-v32opt}"
V32OPT_FLAGS="${V32OPT_FLAGS:--O3}"
PNG2VIRCON="${PNG2VIRCON:-png2vircon}"
WAV2VIRCON="${WAV2VIRCON:-wav2vircon}"

# the tools this build needs
need_tool "$V32AS"
need_tool "$PACKROM"
need_tool "$PNG2VIRCON"
need_tool "$WAV2VIRCON"

# the optimizer is optional: without it (or with NO_OPT set) only the regular cartridge is built
HAVE_OPT=0
OPT_OK=0
if [ -z "$NO_OPT" ] && command -v "$V32OPT" >/dev/null 2>&1; then
    HAVE_OPT=1
else
    echo "note: v32opt not used -- skipping the optimized (Opt) build"
fi

# create the output folders, since the development tools will not
mkdir -p bin || abort_build

echo
echo Optimize the ASM code
echo --------------------------
if [ "$HAVE_OPT" = 1 ]; then
    if "$V32AS" -E -P -c game.asm -o gamePre.asm --no-build-scripts && "$V32OPT" $V32OPT_FLAGS gamePre.asm -o gameOpt.asm; then
        OPT_OK=1
    else
        echo "warning: v32opt failed -- skipping the optimized (Opt) build"
    fi
fi

echo
echo Assemble the ASM code
echo --------------------------
"$V32AS" -c game.asm -o game.vbin --rom-xml game.xml --rom-xml-opt gameOpt.xml --no-build-scripts || abort_build
if [ "$OPT_OK" = 1 ]; then
    "$V32AS" -c gameOpt.asm -o gameOpt.vbin --no-build-scripts || { echo "warning: the optimized code did not assemble -- skipping the optimized (Opt) build"; OPT_OK=0; }
fi

echo
echo Convert the textures and sounds
echo --------------------------
"$PNG2VIRCON" gfx/font.png -o font.vtex || abort_build
"$PNG2VIRCON" gfx/bg.png -o bg.vtex || abort_build
"$WAV2VIRCON" snd/boom.wav -o boom.vsnd || abort_build

echo
echo Pack the ROM
echo --------------------------
"$PACKROM" game.xml -o bin/game.v32 || abort_build
if [ "$OPT_OK" = 1 ]; then
    "$PACKROM" gameOpt.xml -o bin/gameOpt.v32 || echo "warning: the optimized (Opt) cartridge could not be packed"
fi

echo
echo BUILD SUCCESSFUL
